#!/usr/bin/env python3
"""Build everything in dist/ and the self-contained skill from the sources.

Sources: tokens/tokens.json, brand/**/*.md, tools/rules.json, tools/check_copy.py.
Outputs (never edit by hand):
  dist/tokens.css            CSS variables (--df-*), light and dark themes, type classes (.df-*), @font-face
  dist/tailwind-preset.cjs   Tailwind preset: colours under df-*, Manrope, radii, type sizes
  dist/tokens.dtcg.json      W3C design-token format, for Figma plugins and Style Dictionary
  dist/brand-context.md      every writing and visual rule in one file, for chat tools and any model
  skills/doefin-brand/       rules.json, scripts/check_copy.py, reference/brand-context.md and reference/links.md copied in

usage: python3 scripts/build.py
"""
import json
import re
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DIST = ROOT / "dist"
SKILL = ROOT / "skills" / "doefin-brand"
VERSION = (ROOT / "VERSION").read_text().strip()
BANNER = f"Doefin brand {VERSION}. Generated by scripts/build.py from the repository sources. Do not edit by hand."

tokens = json.loads((ROOT / "tokens" / "tokens.json").read_text())
themes = [t["id"] for t in tokens["color"]["themes"]]


def value(v, theme):
    return v if isinstance(v, str) else v.get(theme, v.get(themes[0]))


def css():
    out = [f"/* {BANNER} */",
           "@font-face { font-family: Manrope; src: url(\"../assets/fonts/Manrope-latin.woff2\") format(\"woff2\"); "
           "font-weight: 200 800; font-style: normal; font-display: swap; }"]
    for i, theme in enumerate(themes):
        selector = f':root, [data-theme="{theme}"]' if i == 0 else f'[data-theme="{theme}"]'
        decls = [f"  --df-{t['name']}: {value(t['value'], theme)};" for t in tokens["color"]["tokens"]]
        decls += [f"  --df-{t['name']}: {value(t['value'], theme)};" for t in tokens["shadow"]["tokens"]]
        if i:
            decls.append("  color-scheme: light;")
        out.append(f"{selector} {{\n" + "\n".join(decls) + "\n}")
    rest = [f"  --df-{t['name']}: {t['value']};" for fam in ("spacing", "radius", "layout") for t in tokens[fam]["tokens"]]
    rest += [f"  --df-font-{k}: {v};" for k, v in tokens["type"]["families"].items()]
    out.append(":root {\n" + "\n".join(rest) + "\n}")
    for group in tokens["type"]["groups"]:
        for s in group["styles"]:
            family = s.get("family", group["family"])
            decl = (f"font-family: var(--df-font-{family}); font-size: {s['fontSize']}; "
                    f"line-height: {s['lineHeight']}; font-weight: {s['fontWeight']};")
            if "letterSpacing" in s:
                decl += f" letter-spacing: {s['letterSpacing']};"
            if s["name"] == "label":
                decl += " text-transform: uppercase;"
            if group["name"] == "Figures":
                decl += " font-variant-numeric: tabular-nums;"
            out.append(f".df-{s['name']} {{ {decl} }}")
    return "\n".join(out) + "\n"


def tailwind():
    colors = {t["name"]: f"var(--df-{t['name']})" for t in tokens["color"]["tokens"]}
    radius = {t["name"].replace("radius-", "df-"): t["value"] for t in tokens["radius"]["tokens"]}
    sizes = {}
    for group in tokens["type"]["groups"]:
        for s in group["styles"]:
            extra = {"lineHeight": s["lineHeight"], "fontWeight": str(s["fontWeight"])}
            if "letterSpacing" in s:
                extra["letterSpacing"] = s["letterSpacing"]
            sizes[f"df-{s['name']}"] = [s["fontSize"], extra]
    layout = {t["name"]: t["value"] for t in tokens["layout"]["tokens"]}
    preset = {
        "theme": {"extend": {
            "colors": {"df": colors},
            "fontFamily": {"sans": ["Manrope", "Segoe UI", "system-ui", "sans-serif"],
                           "mono": ["ui-monospace", "SF Mono", "Menlo", "Consolas", "monospace"]},
            "fontSize": sizes,
            "borderRadius": radius,
            "boxShadow": {"df-float": "var(--df-shadow-float)"},
            "maxWidth": {"df-measure": layout["measure"], "df-container": layout["container"]},
        }},
    }
    return (f"// {BANNER}\n// Import dist/tokens.css once in your app so the var(--df-*) values exist.\n"
            f"module.exports = {json.dumps(preset, indent=2)};\n")


def dtcg():
    out = {"$description": BANNER, "color": {}, "spacing": {}, "radius": {}, "font": {}}
    for t in tokens["color"]["tokens"]:
        modes = {th: value(t["value"], th) for th in themes}
        out["color"][t["name"]] = {"$type": "color", "$value": modes[themes[0]], "$description": t["usage"],
                                   "$extensions": {"com.doefin.modes": modes}}
    for fam in ("spacing", "radius"):
        for t in tokens[fam]["tokens"]:
            out[fam][t["name"]] = {"$type": "dimension", "$value": t["value"], "$description": t["usage"]}
    for k, v in tokens["type"]["families"].items():
        out["font"][k] = {"$type": "fontFamily", "$value": [f.strip().strip('"') for f in v.split(",")]}
    for group in tokens["type"]["groups"]:
        for s in group["styles"]:
            out["font"][s["name"]] = {"$type": "typography", "$description": s.get("usage", ""), "$value": {
                "fontFamily": f"{{font.{s.get('family', group['family'])}}}", "fontSize": s["fontSize"],
                "lineHeight": s["lineHeight"], "fontWeight": s["fontWeight"], "letterSpacing": s.get("letterSpacing", "0")}}
    return json.dumps(out, indent=2) + "\n"


def context():
    order = ["overview.md", "voice.md", "compliance.md", "content-types.md",
             "channels/website.md", "channels/social.md", "channels/email.md", "channels/decks.md", "channels/documents.md",
             "visual.md", "decisions.md", "voice-samples.md"]
    parts = [f"<!-- {BANNER} -->\n\n# Doefin brand context\n\n"
             "Every rule for writing and designing for Doefin, in one file. Follow it for any Doefin copy, post, email, "
             "newsletter, deck, document, glossary entry or interface. Where files below disagree, compliance wins, then voice.\n"]
    for name in order:
        text = (ROOT / "brand" / name).read_text()
        text = re.sub(r"^!\[[^\]]*\]\([^)]*\)\n\n?", "", text, flags=re.M)      # pictures don't travel in a text file
        text = re.sub(r"^(#+) ", lambda m: "#" + m.group(1) + " ", text, flags=re.M)  # demote one level under the H1
        parts.append(f"\n<!-- source: brand/{name} -->\n" + text.strip() + "\n")
    return "\n".join(parts)


def main():
    DIST.mkdir(exist_ok=True)
    files = {"tokens.css": css(), "tailwind-preset.cjs": tailwind(), "tokens.dtcg.json": dtcg(), "brand-context.md": context()}
    for name, text in files.items():
        (DIST / name).write_text(text)
    (SKILL / "scripts").mkdir(parents=True, exist_ok=True)
    (SKILL / "reference").mkdir(exist_ok=True)
    shutil.copy2(ROOT / "tools" / "rules.json", SKILL / "rules.json")
    shutil.copy2(ROOT / "tools" / "check_copy.py", SKILL / "scripts" / "check_copy.py")
    shutil.copy2(DIST / "brand-context.md", SKILL / "reference" / "brand-context.md")
    shutil.copy2(ROOT / "links.md", SKILL / "reference" / "links.md")
    for name, text in files.items():
        extra = f", {len(text.split())} words" if name.endswith(".md") else ""
        print(f"dist/{name:22s} {len(text.encode()):>7} bytes{extra}")
    print("skills/doefin-brand/      rules.json, scripts/check_copy.py, reference/brand-context.md")


if __name__ == "__main__":
    main()
